3. Создайте новый файл `commands/ban.js` и вставьте следующий код для реализации команды бан:

```javascript
const { CommandInteraction, MessageEmbed } = require('discord.js');

module.exports = {
  name: 'ban',
  description: 'Банит указанного пользователя',

  execute: async (interaction) => {
    // Получаем пользователя, которого необходимо забанить
    const user = interaction.options.getUser('user');

    // Проверяем, имеет ли пользователь необходимые права для бана
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'У вас недостаточно прав для выполнения этой команды!',
        ephemeral: true,
      });
