    if (!interaction.guild.members.me.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'У меня недостаточно прав для выполнения этой команды!',
        ephemeral: true,
      });
    }

    // Банит пользователя
    try {
      await interaction.guild.members.ban(user, { days: 0, reason: 'Команда /ban' });
      const embed = new MessageEmbed()
        .setTitle('Пользователь был забанен')
        .addField('Ник пользователя', `${user.username}#${user.discriminator}`, true)
        .addField('ID пользователя', user.id, true)
        .addField('Причина бана', 'Команда /ban');

      await interaction.reply({ embeds: [embed] });
    } catch (error) {
      console.error(error);
      await interaction.reply({
        content: 'Ошибка при выполнении команды!',
        ephemeral: true,
      });
    }
  },
