```cpp
#include <string>
#include <sstream>
#include <algorithm>

std::string convertToHtml(const std::string& text_in_quote_format) {
    std::string text_in_html_format;

    // Преобразование в HTML-формат с помощью регулярных выражений
    std::regex quote_regex(R"((?:(?:\'|\"|\u2018|\u2019|\u2032|\u2033)\s*)?[\'\"]?)(.*?)(?:(?:\'|\"|\u2018|\u2019|\u2032|\u2033)\s*)?[\'\"]?)", std::regex::extended);
    std::smatch match;

    std::string current_quote;
    bool in_quote = false;

    std::stringstream html_stream;

    for (const auto& word : std::sregex_token_iterator(text_in_quote_format.begin(), text_in_quote_format.end(), quote_regex, -1)) {
        if (word.empty()) {
            // Рассматриваем нецитированные слова
            html_stream << word << ' ';
        } else {
            // Рассматриваем цитированные слова
            auto quote_char = word.front();
            current_quote += quote_char;
            in_quote = !in_quote;

            html_stream << "<" << (in_quote ? "q" : "blockquote");
            html_stream << ' ';

            std::string quoted_text = word.substr(1, word.length() - 2);
            std::transform(quoted_text.begin(), quoted_text.end(), quoted_text.begin(), [](unsigned char c) {
                if (c == '\'' || c == '"') {
                    // Заменяем специальные символы цитирования на HTML-эквиваленты
                    return c == '\'' ? "&apos;" : "&quot;";
                }
                return c;
            });

            html_stream << quoted_text << ' ';
            html_stream << "</" << (in_quote ? "q" : "blockquote") << ' ';
        }
    }

    // Убираем последний пробел
    text_in_html_format = html_stream.str().substr(0, html_stream.str().length() - 1);
    current_quote.pop_back(); // Убираем последнюю цитировальную апострофу/кавычу

    // Добавляем теги для начала и конца цитирования
    text_in_html_format = "<" + (current_quote.empty() ? "blockquote" : "q") + " " + current_quote + ">" + text_in_html_format + "</" + (current_quote.empty() ? "blockquote" : "q") + ">";

    return text_in_html_format;
}
```

Функция `convertToHtml` принимает ссылку на `std::string`, содержащую текст в формате уценки (с использованием кавычек, апострофов и некоторых других специальных символов), и возвращает строку в HTML-формате, включающую теги `<q>` и `<blockquote>` для обрамления цитированных фрагментов.

Реализация основана на использовании регулярных выражений для разбиения входной строки на цитированные и нецитированные слова, а также на преобразовании специальных символов цитирования в HTML-эквиваленты.

В данном примере также использованы библиотеки `regex`, `sstream` и `algorithm`.

